//! Dead-code elimination must preserve the observable byte returned by boolless.
//! The optional historical C++ snapshot remains diagnostic, not the success criterion.

mod common;
#[path = "common/corpus.rs"]
mod corpus;

use corpus::{assert_c_behavior, repo_root, Corpus, C_TYPES};
use kuna_decomp::dtype::type_metatype;
use kuna_num::opcodes::OpCode;

#[test]
fn boolless_deadcode_preserves_global_read_and_return() {
    let mut corpus = Corpus::load("boolless");
    // Name the input by its real storage instead of pinning an autogenerated
    // global name. The instruction bytes and script remain unchanged.
    corpus.command("map addr [INTMEM,0x52] uint1 input_byte")
        .expect("name boolless's byte input");
    let data = corpus.run_to_function("boolless");
    let fd = data.fd.as_ref().expect("script decompiled boolless");
    let proto = fd.get_func_proto();
    assert_eq!(proto.num_params(), 0);
    assert_eq!(proto.get_output().get_size(), 1, "8051 ACC is a byte return, not void");
    assert_eq!(
        proto.get_output_type().expect("recovered return type").get_metatype(),
        type_metatype::TYPE_UINT,
        "the global byte must not become a signed return"
    );

    let alive: Vec<_> = fd.obank().iter_alive().collect();
    let returns: Vec<_> = alive.iter()
        .map(|&id| fd.obank().get(id).unwrap())
        .filter(|op| op.code() == OpCode::CPUI_RETURN)
        .collect();
    assert!(!returns.is_empty(), "boolless must return to its caller");
    for op in returns {
        let value = op.get_in(1).expect("RETURN must retain its observable value");
        assert_eq!(fd.vbank().get(value).unwrap().get_size(), 1);
    }

    // Preserve the pre-existing optional C++ diagnostic; do not generate or
    // rebaseline a snapshot and do not turn missing oracle data into a gate.
    use std::collections::BTreeMap;
    let mut by_code: BTreeMap<String, usize> = BTreeMap::new();
    for &op in &alive {
        *by_code.entry(format!("{:?}", fd.obank().get(op).unwrap().code())).or_default() += 1;
    }
    if let Some(b4) = b4_snapshot("boolless") {
        let cpp_ops = cpp_b4_op_count(&b4);
        let cpp_codes = cpp_b4_opcode_multiset(&b4);
        eprintln!("C++ B4 alive op-lines: {cpp_ops}");
        eprintln!("C++ B4 opcode multiset: {cpp_codes:?}");
        let matched = opcode_multiset_overlap(&by_code, &cpp_codes);
        eprintln!("Rust/B4 opcode-multiset overlap: {matched} / {cpp_ops}");
        eprintln!("--- C++ B4 ---\n{}\n--- end B4 ---", b4);
    } else {
        eprintln!("(no C++ B4 snapshot to compare against; semantic assertions still run)");
    }

    let body = corpus.render_c();
    assert_c_behavior(
        "boolless-byte-return",
        &format!("{C_TYPES}\nuint1 input_byte;"),
        &body,
        r#"
int main(void) {
    for (unsigned input = 0; input < 256; ++input) {
        input_byte = input;
        unsigned actual = boolless();
        unsigned expected = input < 11 ? 1 : input;
        if (actual != expected || input_byte != input) return 1;
    }
    return 0;
}
"#,
    );
}

/// The number of alive op-lines (basic-block op lines) in the C++ B4 snapshot.
fn cpp_b4_op_count(b4: &str) -> usize {
    b4.lines()
        .filter(|l| {
            // A B4 raw op line starts with the seqnum address "0x..:..:".
            l.starts_with("0x") && l.contains(":\t")
        })
        .count()
}

fn b4_snapshot(stem: &str) -> Option<String> {
    let p = repo_root().join("tests/golden/snapshots/cpp").join(stem).join("000-B4.txt");
    std::fs::read_to_string(p).ok()
}

/// Per-opcode multiset of the C++ B4 raw op-lines (the opcode keyword of each
/// `0x..:..:` basic-block op line, mapped to its Rust `CPUI_*` name).
fn cpp_b4_opcode_multiset(b4: &str) -> std::collections::BTreeMap<String, usize> {
    use std::collections::BTreeMap;
    let mut out: BTreeMap<String, usize> = BTreeMap::new();
    for l in b4.lines() {
        if !(l.starts_with("0x") && l.contains(":\t")) {
            continue;
        }
        let body = l.split(":\t").nth(1).unwrap_or("");
        // Recognize the printer's symbolic forms (typeop.cc printRaw):
        let code = if body.contains(" <= ") {
            "CPUI_INT_LESSEQUAL"
        } else if body.contains(" < ") {
            "CPUI_INT_LESS"
        } else if body.contains(" ? ") {
            "CPUI_MULTIEQUAL"
        } else if body.starts_with("goto") || body.contains(" if (") {
            "CPUI_CBRANCH"
        } else if body.starts_with("return") {
            "CPUI_RETURN"
        } else if body.contains(" = ") && !body.contains('(') {
            // `out = in` plain assignment -> COPY (the B4 ACC=#1 / i0x52=i0x52).
            "CPUI_COPY"
        } else {
            "OTHER"
        };
        *out.entry(code.to_string()).or_default() += 1;
    }
    out
}

/// Number of op-classes the Rust IR shares with the C++ B4 (multiset overlap,
/// counting min multiplicity per class).
fn opcode_multiset_overlap(
    rust: &std::collections::BTreeMap<String, usize>,
    cpp: &std::collections::BTreeMap<String, usize>,
) -> usize {
    cpp.iter().map(|(k, &cv)| rust.get(k).copied().unwrap_or(0).min(cv)).sum()
}
